package dev.rag.knowledge;
import dev.rag.common.*;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Element;
import org.springframework.stereotype.Component;
import java.nio.*;
import java.nio.charset.*;
import java.util.*;

@Component
public class StructuredParser {
 public record Unit(String key,String kind,String text,Map<String,Object> location,boolean machine,String imageData){ public Unit { location=new LinkedHashMap<>(location); } }
 public record Result(List<Unit> units,List<Map<String,Object>> warnings){}
 public static String utf8(byte[] b){try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString().replace("\uFEFF","");}catch(CharacterCodingException e){throw new ApiException(422,"ENCODING_INVALID","文档必须为 UTF-8");}}
 public Result parse(byte[] bytes,String name){String text=utf8(bytes).replace("\r\n","\n").replace('\r','\n');String lower=name.toLowerCase(Locale.ROOT);if(lower.endsWith(".jsonl"))return faq(text);if(lower.endsWith(".html")||lower.endsWith(".htm"))return html(text);return markdown(text);}
 private Result faq(String text){List<Unit> result=new ArrayList<>();int line=0;for(String raw:text.split("\n")){line++;if(raw.isBlank())continue;var row=Json.object(raw);String q=Json.str(row,"question"),a=Json.str(row,"answer");if(q.isBlank()||a.isBlank())throw new ApiException(422,"FAQ_INVALID","FAQ 第 "+line+" 行缺少 question/answer");result.add(new Unit("line:"+line,"TEXT","问题："+q+"\n答案："+a,Map.of("line",line,"faq",true),false,null));}return checked(result,List.of());}
 private Result html(String text){var doc=Jsoup.parse(text);doc.select("script,style,iframe,object,embed,svg").remove();List<Unit> units=new ArrayList<>();List<Map<String,Object>> warnings=new ArrayList<>();int n=0;for(Element e:doc.select("h1,h2,h3,h4,h5,h6,p,pre,table,li,img")){if(e.parents().stream().anyMatch(p->Set.of("table","pre","li").contains(p.tagName())))continue;String kind=e.tagName().matches("h[1-6]")?"HEADING":e.tagName().equals("table")?"TABLE":e.tagName().equals("pre")?"CODE":"TEXT";Map<String,Object> loc=new LinkedHashMap<>(Map.of("paragraph",++n));String value=e.wholeText();if(e.tagName().equals("img")){warnings.add(Map.of("code","IMAGE_ATTACHMENT_REQUIRED","unit",n));continue;}if(kind.equals("TABLE")){var rows=e.select("tr").stream().map(r->r.select("th,td").eachText()).toList();loc.put("rows",rows);int headerRows=0;for(Element row:e.select("tr")){if(row.select("th").isEmpty())break;headerRows++;}loc.put("headerRowCount",headerRows);loc.put("cells",e.select("th,td").stream().map(c->Map.of("text",c.text(),"rowspan",c.attr("rowspan"),"colspan",c.attr("colspan"))).toList());value=rows.stream().map(r->String.join(" | ",r)).reduce((a,b)->a+"\n"+b).orElse("");}if(!value.isBlank())units.add(new Unit("paragraph:"+n,kind,value,loc,false,null));}return checked(units,warnings);}
 private Result markdown(String text){List<Unit> units=new ArrayList<>();List<Map<String,Object>> warnings=new ArrayList<>();String[] lines=text.split("\n",-1);StringBuilder current=new StringBuilder();String kind="TEXT",heading="";int start=1;boolean code=false;String fence="";for(int i=0;i<lines.length;i++){String line=lines[i];boolean marker=line.stripLeading().startsWith("```")||line.stripLeading().startsWith("~~~");if(marker){if(!code){flush(units,current,kind,start,i,heading);kind="CODE";start=i+1;fence=line.stripLeading().substring(0,3);code=true;current.append(line).append('\n');}else{current.append(line).append('\n');if(line.stripLeading().startsWith(fence)){flush(units,current,kind,start,i+1,heading);code=false;kind="TEXT";start=i+2;}}continue;}if(code){current.append(line).append('\n');continue;}if(line.matches("^#{1,6}\\s+.*")){flush(units,current,kind,start,i,heading);heading=line.replaceFirst("^#+\\s+","");units.add(new Unit("line:"+(i+1),"HEADING",heading,Map.of("lineStart",i+1,"lineEnd",i+1,"heading",heading),false,null));start=i+2;kind="TEXT";}else if(line.isBlank()){flush(units,current,kind,start,i,heading);start=i+2;kind="TEXT";}else{if(current.isEmpty())start=i+1;if(line.contains("|")&&(kind.equals("TABLE")||i+1<lines.length&&lines[i+1].matches("^[ |:.-]+$")))kind="TABLE";current.append(line).append('\n');if(line.contains("!["))warnings.add(Map.of("code","IMAGE_ATTACHMENT_REQUIRED","line",i+1));}}flush(units,current,kind,start,lines.length,heading);if(code)warnings.add(Map.of("code","UNCLOSED_CODE_FENCE","line",start));return checked(units,warnings);}
 private void flush(List<Unit> units,StringBuilder text,String kind,int start,int end,String heading){String value=text.toString().stripTrailing();if(!value.isBlank())units.add(new Unit("line:"+start,kind,value,Map.of("lineStart",start,"lineEnd",end,"heading",heading),false,null));text.setLength(0);}
 private Result checked(List<Unit> units,List<Map<String,Object>> warnings){if(units.isEmpty())throw new ApiException(422,"EMPTY_DOCUMENT","文档没有可读内容");if(units.size()>10000)throw new ApiException(413,"INPUT_TOO_LARGE","来源单元超过上限");return new Result(units,warnings);}
}
